renderCategoryTree.body:
const result = await api("/api/tool", { tool: "knowledge.category.list", arguments: { include_inactive: false } });
      if (result.ok && Array.isArray(result.result)) {
        const categories = result.result;
        const parentMap = {};
        categories.forEach(cat => {
          const parentKey = cat.parent_id === null || cat.parent_id === 'null' || cat.parent_id === '' ? 'root' : cat.parent_id;
          if (!parentMap[parentKey]) parentMap[parentKey] = [];
          parentMap[parentKey].push(cat);
        });

        const container = $("kbCategoryTree");
        container.innerHTML = '';

        function buildTree(parentKey, depth = 0, parentElement = container) {
          const children = parentMap[parentKey] || [];
          if (children.length === 0) return;

          children.forEach(cat => {
            const childKey = cat.id;
            const hasChildren = parentMap[childKey] && parentMap[childKey].length > 0;

            const itemDiv = document.createElement('div');
            itemDiv.style.cursor = 'pointer';
            itemDiv.style.padding = '4px 6px';
            itemDiv.style.borderRadius = '4px';

            itemDiv.onmouseover = () => { itemDiv.style.background = 'var(--bg)'; };
            itemDiv.onmouseout = () => { itemDiv.style.background = 'transparent'; };

            if (hasChildren) {
              const iconSpan = document.createElement('span');
              iconSpan.textContent = '▶';
              iconSpan.style.display = 'inline-block';
              iconSpan.style.width = '18px';
              iconSpan.style.textAlign = 'center';
              iconSpan.style.fontSize = '12px';
              itemDiv.appendChild(iconSpan);
            } else {
              const spacerSpan = document.createElement('span');
              spacerSpan.style.display = 'inline-block';
              spacerSpan.style.width = '18px';
              itemDiv.appendChild(spacerSpan);
            }

            const nameSpan = document.createElement('span');
            nameSpan.textContent = cat.name;

            itemDiv.appendChild(nameSpan);

            itemDiv.addEventListener('click', (e) => {
              if (hasChildren) {
                e.stopPropagation();
                toggleCategory(childKey);
              }
              selectCategory(cat.slug, cat.name);
            });

            parentElement.appendChild(itemDiv);

            if (hasChildren) {
              const childrenContainer = document.createElement('div');
              childrenContainer.id = 'cat-children-' + childKey;
              childrenContainer.style.display = 'block';
              childrenContainer.style.paddingLeft = '20px';
              parentElement.appendChild(childrenContainer);
              buildTree(childKey, depth + 1, childrenContainer);
            }
          });
        }

        buildTree('root', 0);
      }

