setupMenuGroups.body:
// Menu section toggle (Level 1)
      document.querySelectorAll(".menu-section-header").forEach(header => {
        header.addEventListener("click", () => {
          const section = header.closest(".menu-section");
          if (!section) return;
          section.classList.toggle("collapsed");
          // Update ARIA
          header.setAttribute("aria-expanded", !section.classList.contains("collapsed"));
          // Save state to localStorage
          localStorage.setItem(`menu-section-${section.dataset.section}`,
            section.classList.contains("collapsed") ? "collapsed" : "open");
        });
        // Keyboard support
        header.addEventListener("keydown", (e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            header.click();
          }
        });
      });

      // Restore section collapse state
      document.querySelectorAll(".menu-section").forEach(section => {
        const saved = localStorage.getItem(`menu-section-${section.dataset.section}`);
        if (saved === "collapsed") {
          section.classList.add("collapsed");
          const header = section.querySelector(".menu-section-header");
          if (header) header.setAttribute("aria-expanded", "false");
        }
      });

      // Menu group toggle (Level 2)
      document.querySelectorAll(".menu-group").forEach(group => {
        const menuItem = group.querySelector(".menu-item");
        if (menuItem) {
          menuItem.addEventListener("click", () => {
            const hasSubmenu = group.querySelector(".submenu");
            if (hasSubmenu && !sidebarCollapsed) {
              group.classList.toggle("open");
              menuItem.setAttribute("aria-expanded", group.classList.contains("open"));
            }
          });
          // Keyboard support
          menuItem.addEventListener("keydown", (e) => {
            if (e.key === "Enter" || e.key === " ") {
              e.preventDefault();
              menuItem.click();
            }
          });
        }
      });

      // Submenu item clicks (Level 3)
      document.querySelectorAll(".submenu-item").forEach(item => {
        item.addEventListener("click", () => {
          const page = item.dataset.page;
          if (page) goToPage(page);
        });
        // Keyboard support
        item.addEventListener("keydown", (e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            item.click();
          }
        });
      });

