loadSkillList.body:
console.log("[Skill] loadSkillList called");
      const container = $("skillList");
      container.innerHTML = `<p style="padding:12px;color:var(--muted);">${t("status.loading")}</p>`;
      const result = await api("/api/tool", { tool: "skill.list", arguments: { active_only: false } });
      if (!result.ok || !Array.isArray(result.result)) {
        container.innerHTML = `<p style="padding:12px;color:var(--danger);">Failed to load skills</p>`;
        return;
      }
      if (result.result.length === 0) {
        container.innerHTML = `<p style="padding:12px;color:var(--muted);">No skills yet. Click "+ New" to create one.</p>`;
        return;
      }
      container.innerHTML = result.result.map(s => `
        <div class="uk-tree-item" style="cursor:pointer;padding:10px 12px;border-bottom:1px solid var(--line);${skillCurrentId === s.id ? 'background:var(--accent-light);' : ''}"
             onclick="selectSkill('${s.id}')">
          <div style="font-weight:500;font-size:13px;">${escapeHtml(s.name)}</div>
          <div style="font-size:11px;color:var(--muted);margin-top:2px;">${escapeHtml((s.description || '').substring(0, 60))}</div>
          ${!s.is_active ? '<span class="badge" style="background:var(--warning);font-size:9px;margin-top:4px;">Inactive</span>' : ''}
        </div>
      `).join("");

selectSkill.body:
