saveSkill.body:
const id = $("skillEditId").value;
      const name = $("skillEditName").value.trim();
      if (!name) { setStatus("Name required"); return; }
      const desc = $("skillEditDesc").value.trim() || null;
      const triggers = $("skillEditTriggers").value.split(",").map(s => s.trim()).filter(Boolean);
      const tools = $("skillEditTools").value.split(",").map(s => s.trim()).filter(Boolean);
      const sort = parseInt($("skillEditSort").value) || 0;
      const active = $("skillEditActive").checked;
      const content = $("skillEditContent").value;

      let skillResult;
      if (id) {
        skillResult = await api("/api/tool", { tool: "skill.update", arguments: {
          skill_id: id, name, description: desc, content, trigger_words: triggers,
          tool_hints: tools, is_active: active, sort_order: sort,
        }});
      } else {
        skillResult = await api("/api/tool", { tool: "skill.create", arguments: {
          name, description: desc, content, trigger_words: triggers,
          tool_hints: tools, sort_order: sort,
        }});
      }

      if (!skillResult.ok) { setStatus(t("status.error")); return; }

      const skillId = skillResult.result?.id || id;
      if (skillId && skillCurrentSteps.length > 0) {
        await api("/api/tool", { tool: "skill.step.list", arguments: { skill_id: skillId } });
        for (const step of skillCurrentSteps) {
          await api("/api/tool", { tool: "skill.step.add", arguments: {
            skill_id: skillId, step_order: step.step_order, step_name: step.step_name,
            tool_name: step.tool_name, description: step.description,
            parameters: step.parameters, optional: step.optional, conditional: step.conditional,
          }});
        }
      }

      $("skillEditModal").classList.add("hidden");
      await loadSkillList();
      if (skillId) await selectSkill(skillId);
      setStatus(t("msg.saved"));

