init.body:
loadState();
      setupMenuGroups();
      setupDropdown("langBtn", "langMenu");
      setupDropdown("userBtn", "userMenu");

      // Initial project section visibility
      const projectSection = document.querySelector('[data-section="project"]');
      if (projectSection) {
        projectSection.style.display = "block";
      }

      // Sidebar toggle
      $("sidebarToggle").onclick = toggleSidebar;

      // Language dropdown
      document.querySelectorAll("#langMenu .dropdown-item").forEach(item => {
        item.addEventListener("click", () => {
          const lang = item.dataset.lang;
          applyLanguage(lang);
          refreshAuth();
        });
      });

      // User menu
      $("menuSettings").onclick = () => goToPage("system-connection");
      $("menuAccount").onclick = () => goToPage("system-account");
      $("logoutBtn").onclick = async () => {
        await api("/api/logout", {});
        await refreshAuth();
      };

      // AI Models page
      // Load tokens when account page is shown
      const originalPageRouter = goToPage;
      goToPage = function(page) {
        originalPageRouter(page);
        if (page === "system-account") {
          setTimeout(loadApiTokens, 100);
        }
      };

      // Setup / Login
      $("setupButton").onclick = async () => {
        const result = await api("/api/setup", {
          username: $("setupUser").value,
          password: $("setupPassword").value,
          mcp_url: $("setupMcpUrl").value,
          token: $("setupToken").value
        });
        const outputEl = $("output");
        if (outputEl) outputEl.textContent = JSON.stringify(result, null, 2);
        await refreshAuth();
      };

      $("loginButton").onclick = async () => {
        const result = await api("/api/login", {
          username: $("loginUser").value,
          password: $("loginPassword").value
        });
        const outputEl = $("output");
        if (outputEl) outputEl.textContent = JSON.stringify(result, null, 2);
        await refreshAuth();
      };

      // Save connection
      $("save").onclick = () => {
        saveState();
        setStatus(t("status.saved"));
      };

      // Update account
      $("updateAccount").onclick = async () => {
        const result = await api("/api/account", {
          mcp_url: $("accountMcpUrl").value,
          mcp_token: $("accountToken").value
        });
        $("accountToken").value = "";
        const outputEl = $("output");
        if (outputEl) outputEl.textContent = JSON.stringify(result, null, 2);
        window.__hasMcpToken = !!result.has_mcp_token;
        updateTokenState(window.__hasMcpToken);
        setStatus(result.ok ? t("status.accountUpdated") : t("status.error"));
      };

      // Change password
      $("changePasswordBtn").onclick = async () => {
        const current = $("currentPassword").value;
        const newPass = $("newPassword").value;
        const confirm = $("confirmPassword").value;
        if (!current || !newPass || !confirm) {
          setStatus(t("error.allFieldsRequired"));
          return;
        }
        if (newPass !== confirm) {
          setStatus(t("error.passwordMismatch"));
          return;
        }
        if (newPass.length < 6) {
          setStatus(t("error.passwordTooShort"));
          return;
        }
        const result = await api("/api/account", {
          old_password: current,
          new_password: newPass
        });
        if (result.ok) {
          $("currentPassword").value = "";
          $("newPassword").value = "";
          $("confirmPassword").value = "";
          setStatus(t("status.passwordChanged"));
        } else {
          setStatus(t("status.error") + ": " + (result.error || ""));
        }
      };

      // API Tokens management
      async function loadApiTokens() {
        const workspace = $("workspace")?.value || $("workspaceSelect")?.value || null;
        const args = { include_revoked: false };
        if (workspace) args.workspace = workspace;
        const result = await api("/api/tool", {
          tool: "auth.list_api_tokens",
          arguments: args
        });
        const container = $("apiTokensList");
        if (!container) return;
        if (!result.ok || !Array.isArray(result.result)) {
          container.innerHTML = '<div style="color: var(--muted); font-size: 13px; padding: 12px; text-align: center;">' + t("account.loadTokensFailed") + '</div>';
          return;
        }
        const tokens = result.result.filter(t => !t.revoked_at);
        if (tokens.length === 0) {
          container.innerHTML = '<div style="color: var(--muted); font-size: 13px; padding: 12px; text-align: center;">' + t("account.noTokens") + '</div>';
          return;
        }
        container.innerHTML = tokens.map(token => `
          <div style="display: flex; justify-content: space-between; align-items: center; padding: 10px; border-bottom: 1px solid var(--line); font-size: 13px;">
            <div>
              <div style="font-weight: 500;">${escapeHtml(token.name)}</div>
              <div style="color: var(--muted); font-size: 11px;">${(token.scopes || []).join(', ')} · ${token.created_at ? new Date(token.created_at).toLocaleDateString() : ''}</div>
            </div>
            <button class="btn-secondary btn-sm" onclick="revokeToken('${token.id}')" style="font-size: 12px; padding: 4px 8px;">${t("action.revoke")}</button>
          </div>
        `).join('');
      }

      window.revokeToken = async (tokenId) => {
        if (!confirm(t("confirm.revokeToken"))) return;
        const result = await api("/api/tool", {
          tool: "auth.revoke_api_token",
          arguments: { token_id: tokenId }
        });
        if (result.ok) {
          setStatus(t("status.tokenRevoked"));
          loadApiTokens();
        } else {
          setStatus(t("status.error"));
        }
      };

      $("createTokenBtn").onclick = async () => {
        const name = $("tokenName").value.trim();
        if (!name) {
          setStatus(t("error.tokenNameRequired"));
          return;
        }
        const scopes = Array.from(document.querySelectorAll('.token-scope:checked')).map(cb => cb.value);
        if (scopes.length === 0) {
          setStatus(t("error.tokenScopeRequired"));
          return;
        }
        const workspace = $("workspace")?.value || $("workspaceSelect")?.value || null;
        const username = window.__currentUsername;
        const args = { name: name, scopes: scopes, username: username };
        if (workspace) args.workspace = workspace;
        const result = await api("/api/tool", {
          tool: "auth.create_api_token",
          arguments: args
        });
        if (result.ok && result.result && result.result.token) {
          $("newTokenValue").value = result.result.token;
          $("newTokenDisplay").style.display = "block";
          $("tokenName").value = "";
          loadApiTokens();
        } else {
          setStatus(t("status.error") + ": " + (result.error || ""));
        }
      };

      $("copyTokenBtn").onclick = () => {
        const tokenInput = $("newTokenValue");
        tokenInput.select();
        document.execCommand("copy");
        setStatus(t("status.tokenCopied"));
      };

      // Project selector
      $("loadProjects").onclick = loadProjects;
      $("projectSelect").onchange = () => {
        const project = $("projectSelect").value;
        if ($("project")) $("project").value = project;
      };

      // Tool buttons with data-tool
      document.querySelectorAll("[data-tool]").forEach((button) => {
        button.onclick = () => callTool(button.dataset.tool, argsFor(button.dataset.form));
      });

      // Manual tool call
      $("callTool").onclick = () => {
        let args = {};
        try { args = JSON.parse($("toolArgs").value || "{}"); }
        catch (err) {
          const outputEl = $("output");
          if (outputEl) outputEl.textContent = t("error.invalidJson") + ": " + err.message;
          return;
        }
        callTool($("toolName").value, args);
      };

      // ========== Canon buttons ==========
      $("canonUpsert").onclick = async () => {
        const base = getActiveProjectArgs();
        if (!base) return;
        let scopeObj = {};
        const scopeVal = $("canonScope").value;
        if (scopeVal === "volume") scopeObj = { volume_no: 1 };
        else if (scopeVal === "chapter") scopeObj = { chapter_no: 1 };
        const args = {
          ...base,
          key: $("canonKey").value,
          doc_type: $("canonType").value,
          title: $("canonTitle").value,
