        const container = $("councilConfigsResult");
        if (!configs || configs.length === 0) {
          container.innerHTML = '<p style="color:var(--muted);text-align:center;padding:20px;">No council configs</p>';
          return;
        }
        container.innerHTML = configs.map(c => `
          <div class="list-item" onclick="selectCouncilConfig('${c.id}')">
            <div class="list-item-header">
              <span>${c.name}</span>
              ${c.is_active ? '<span class="badge badge-success">Active</span>' : ''}
            </div>
            <div class="list-item-meta">
              ID: ${c.id}
            </div>
          </div>
        `).join("");
      }

      window.selectCouncilConfig = async (configId) => {
        const base = getActiveProjectArgs();
        if (!base) return;
        currentCouncilConfig = configId;
        setStatus(t("status.running"));
        const result = await api("/api/tool", { tool: "review.list_council_configs", arguments: { ...base } });
        if (result.ok && Array.isArray(result.result)) {
          const config = result.result.find(c => c.id === configId);
          if (config) {
            $("councilConfigDetailTitle").textContent = config.name;
            $("councilConfigName").value = config.name;
            $("councilConfigJson").value = JSON.stringify(config.config || {}, null, 2);
            $("councilConfigIsActive").checked = config.is_active;
            $("councilConfigDetailCard").style.display = "block";
            setStatus(t("msg.loaded"));
          }
        }
      };

      $("councilConfigsListBtn").onclick = async () => {
        const base = getActiveProjectArgs();
        if (!base) return;
        setStatus(t("status.running"));
        const result = await api("/api/tool", { tool: "review.list_council_configs", arguments: { ...base } });
        if (result.ok && Array.isArray(result.result)) {
          renderCouncilConfigs(result.result);
          setStatus(t("msg.loaded"));
        } else {
          setStatus(t("status.error"));
        }
      };

      $("councilConfigCreateBtn").onclick = () => {
        currentCouncilConfig = null;
        $("councilConfigDetailTitle").textContent = "New Council Config";
        $("councilConfigName").value = "";
        $("councilConfigJson").value = JSON.stringify({ models: [], dimensions: [] }, null, 2);
        $("councilConfigIsActive").checked = false;
        $("councilConfigDetailCard").style.display = "block";
      };

      $("councilConfigSaveBtn").onclick = async () => {
        const base = getActiveProjectArgs();
        if (!base) return;
        const name = $("councilConfigName").value.trim();
        if (!name) { setStatus(t("status.error") + ": name required"); return; }
        const config = parseJson($("councilConfigJson").value, {});
        const is_active = $("councilConfigIsActive").checked;
        setStatus(t("status.running"));
        const result = await api("/api/tool", { tool: "review.upsert_council_config", arguments: { ...base, name, config, is_active } });
        if (result.ok) {
          setStatus(t("msg.saved"));
          $("councilConfigDetailCard").style.display = "none";
          $("councilConfigsListBtn").click();
        } else {
          setStatus(t("status.error"));
        }
      };

      $("councilConfigActivateBtn").onclick = async () => {
        const base = getActiveProjectArgs();
        if (!base) return;
        const name = $("councilConfigName").value.trim();
        if (!name) return;
        const config = parseJson($("councilConfigJson").value, {});
        setStatus(t("status.running"));
        const result = await api("/api/tool", { tool: "review.upsert_council_config", arguments: { ...base, name, config, is_active: true } });
        if (result.ok) {
          setStatus(t("msg.saved"));
          $("councilConfigIsActive").checked = true;
        } else {
          setStatus(t("status.error"));
        }
      };

      $("councilConfigCloseBtn").onclick = () => {
        $("councilConfigDetailCard").style.display = "none";
        currentCouncilConfig = null;
      };

      // ========== Knowledge Base handlers ==========

      // Navigate to knowledge list with category filter
      window.goToKnowledgeList = (categorySlug) => {
        $("kbListCategory").value = categorySlug || "";
        loadKnowledgeList();
        goToPage("knowledge-list");
      };

      // Select and load knowledge item for editing
      window.selectKnowledgeItem = async (id, code) => {
        const args = { item_id: id, increment_view: false };
        const result = await api("/api/tool", { tool: "knowledge.item.get", arguments: args });
        if (result.ok && result.result) {
          const item = result.result;
          $("kbCode").value = item.code || "";
          $("kbCode").readOnly = true;
          $("kbCategory").value = item.category_slug || "";
          $("kbTitle").value = item.title || "";
          $("kbContent").value = item.content || "";
          $("kbSummary").value = item.summary || "";
          $("kbExamples").value = item.examples || "";
          $("kbCounterExamples").value = item.counter_examples || "";
          $("kbApplicableGenres").value = (item.applicable_genres || []).join(", ");
          $("kbApplicableSkills").value = (item.applicable_skills || []).join(", ");
          $("kbDeleteBtn").style.display = "inline-flex";
          $("kbItemPreview").style.display = "block";
          $("kbItemPreviewContent").innerHTML = renderKnowledgeItemDetail(item);
          goToPage("knowledge-edit");
        }
      };

      function renderKnowledgeItemDetail(item) {
        return `
          <div style="padding: 12px; background: var(--bg); border-radius: 6px;">
            <div style="margin-bottom: 8px;"><strong>Code:</strong> ${item.code}</div>
            <div style="margin-bottom: 8px;"><strong>Category:</strong> ${item.category_name || item.category_slug || 'N/A'}</div>
            <div style="margin-bottom: 8px;"><strong>Level:</strong> ${item.level || 'N/A'}</div>
            <div style="margin-bottom: 8px;"><strong>Source:</strong> ${item.source || 'N/A'}</div>
            ${item.applicable_genres && item.applicable_genres.length ? `<div style="margin-bottom: 8px;"><strong>Genres:</strong> ${item.applicable_genres.join(', ')}</div>` : ''}
            ${item.applicable_skills && item.applicable_skills.length ? `<div style="margin-bottom: 8px;"><strong>Skills:</strong> ${item.applicable_skills.join(', ')}</div>` : ''}
            <div style="margin-bottom: 8px;"><strong>Views:</strong> ${item.view_count || 0} | <strong>Uses:</strong> ${item.use_count || 0}</div>
            <div style="margin-bottom: 8px;"><strong>Created:</strong> ${item.created_at || 'N/A'}</div>
            <div><strong>Updated:</strong> ${item.updated_at || 'N/A'}</div>
          </div>
        `;
      }

      // Save Knowledge Item
      window.saveKnowledgeItem = async () => {
        const code = $("kbCode").value.trim();
        const title = $("kbTitle").value.trim();
        const content = $("kbContent").value.trim();

        if (!code || !title || !content) {
          setStatus("Code, Title and Content are required");
          return;
        }

        setStatus(t("status.running"));
        const args = {
          code,
          title,
          content,
          summary: $("kbSummary").value.trim() || null,
          category_slug: $("kbCategory").value || null,
          examples: $("kbExamples").value.trim() || null,
          counter_examples: $("kbCounterExamples").value.trim() || null,
          applicable_genres: $("kbApplicableGenres").value.split(",").map(s => s.trim()).filter(Boolean) || null,
          applicable_skills: $("kbApplicableSkills").value.split(",").map(s => s.trim()).filter(Boolean) || null,
          source: "manual",
        };

        const result = await api("/api/tool", { tool: "knowledge.item.upsert", arguments: args });
        if (result.ok) {
          setStatus(t("msg.saved"));
          loadKnowledgeStats();
        } else {
          setStatus(t("status.error") + ": " + (result.error || ""));
        }
      };

      // Clear Knowledge Form
      window.clearKnowledgeForm = () => {
        $("kbCode").value = "";
        $("kbCode").readOnly = false;
        $("kbCategory").value = "";
        $("kbTitle").value = "";
        $("kbContent").value = "";
        $("kbSummary").value = "";
        $("kbExamples").value = "";
        $("kbCounterExamples").value = "";
        $("kbApplicableGenres").value = "";
        $("kbApplicableSkills").value = "";
        $("kbDeleteBtn").style.display = "none";
        $("kbItemPreview").style.display = "none";
      };

      // Delete Knowledge Item
      window.deleteKnowledgeItem = async () => {
        const code = $("kbCode").value.trim();
        if (!code) return;

        if (!confirm(`Delete knowledge item "${code}"?`)) return;

        setStatus(t("status.running"));
        const result = await api("/api/tool", { tool: "knowledge.item.delete", arguments: { code } });
        if (result.ok) {
          setStatus("Item deleted");
          clearKnowledgeForm();
          loadKnowledgeStats();
        } else {
          setStatus(t("status.error"));
        }
      };

      // Search Knowledge
      window.searchKnowledge = async () => {
        const query = $("kbSearchQuery").value.trim();
        if (!query) {
          setStatus("Please enter search query");
          return;
        }

        setStatus(t("status.running"));
        const args = {
          query,
          category_slug: $("kbSearchCategory").value || null,
          applicable_genre: $("kbSearchGenre").value || null,
          limit: parseInt($("kbSearchLimit").value) || 20,
        };

        const result = await api("/api/tool", { tool: "knowledge.item.search", arguments: args });
        if (result.ok && Array.isArray(result.result)) {
          const items = result.result;
          const container = $("knowledgeSearchResult");
          if (items.length === 0) {
            container.innerHTML = '<p style="color:var(--muted);text-align:center;padding:20px;">No results found</p>';
          } else {
            container.innerHTML = items.map(item => `
              <div class="list-item" onclick="selectKnowledgeItem('${item.id}', '${item.code}')" style="cursor: pointer;">
                <div class="list-item-header">
                  <span style="font-weight: 600;">${item.title || item.code}</span>
                  <span class="badge" style="background: var(--accent-light); color: var(--accent);">${item.category_name || item.category_slug}</span>
                </div>
                <div class="list-item-meta">
                  <span style="font-weight:500;">${item.code}</span>
                  ${item.level ? `<span style="margin:0 6px;">|</span><span>${item.level}</span>` : ''}
                </div>
                <div style="font-size:12px;color:var(--muted);margin-top:6px;line-height:1.5;">
                  <strong>Summary:</strong> ${(item.summary || '').substring(0, 200)}${(item.summary || '').length > 200 ? '...' : ''}
                </div>
                ${item.applicable_genres && item.applicable_genres.length ? `
                  <div style="margin-top: 6px;">
                    <span style="font-size: 11px; color: var(--accent);">Genres: ${item.applicable_genres.slice(0, 5).join(', ')}</span>
                  </div>
                ` : ''}
              </div>
            `).join("");
          }
          setStatus(`Found ${items.length} results`);
        } else {
          setStatus(t("status.error"));
        }
      };

      // ========== Chapter Plans handlers ==========

      function renderChapterPlans(plans) {
        const container = $("chapterPlansResult");
        const countBadge = $("chapterPlansCount");
        if (!plans || plans.length === 0) {
          container.innerHTML = '<p style="color:var(--muted);text-align:center;padding:20px;">No chapter plans</p>';
          countBadge.textContent = "0";
          return;
        }
        countBadge.textContent = plans.length;
        container.innerHTML = plans.map(p => `
          <div class="list-item" onclick="selectChapterPlan('${p.id}')">
            <div class="list-item-header">
              <span>Chapter ${p.chapter_no}</span>
              <div style="display:flex;gap:6px;">
                <span class="badge ${p.status === 'completed' ? 'badge-success' : p.status === 'writing' ? 'badge-warning' : p.status === 'skipped' ? 'badge-archived' : 'badge-active'}">${p.status}</span>
              </div>
            </div>
            <div class="list-item-meta">
              ID: ${p.id} | ${p.updated_at || p.created_at || '-'}
            </div>
          </div>
        `).join("");
      }

      let currentChapterPlan = null;

      window.selectChapterPlan = async (planId) => {
        const base = getActiveProjectArgs();
        if (!base) return;
        currentChapterPlan = planId;
        setStatus(t("status.running"));
        const result = await api("/api/tool", { tool: "plot.list_chapter_plans", arguments: { ...base, status: null } });
        if (result.ok && Array.isArray(result.result)) {
          const plan = result.result.find(p => p.id === planId);
          if (plan) {
            $("chapterPlanDetailTitle").textContent = `Chapter ${plan.chapter_no} Plan`;
            $("chapterPlanDetailContent").innerHTML = `
              <div class="form-row">
                <div class="form-group">
                  <label class="form-label" data-i18n="field.chapterNo">Chapter No</label>
                  <input class="form-input" value="${plan.chapter_no}" readonly>
                </div>
                <div class="form-group">
                  <label class="form-label" data-i18n="field.status">Status</label>
                  <input class="form-input" value="${plan.status}" readonly>
                </div>
                <div class="form-group">
                  <label class="form-label" data-i18n="field.updatedAt">Updated At</label>
                  <input class="form-input" value="${plan.updated_at || plan.created_at || '-'}" readonly>
                </div>
              </div>
              <div class="form-group">
                <label class="form-label" data-i18n="field.plan">Plan Content</label>
                <textarea class="form-textarea" rows="10" readonly>${escapeHtml(JSON.stringify(plan.plan || {}, null, 2))}</textarea>
              </div>
            `;
            $("chapterPlanDetailCard").style.display = "block";
            setStatus(t("msg.loaded"));
          }
        }
      };

      $("chapterPlansListBtn").onclick = async () => {
        const base = getActiveProjectArgs();
        if (!base) return;
        setStatus(t("status.running"));
        const status = $("chapterPlanStatus").value || null;
        const result = await api("/api/tool", { tool: "plot.list_chapter_plans", arguments: { ...base, status, limit: 100 } });
        if (result.ok && Array.isArray(result.result)) {
          renderChapterPlans(result.result);
          setStatus(t("msg.loaded"));
        } else {
          setStatus(t("status.error"));
        }
      };

      $("chapterPlanCloseBtn").onclick = () => {
        $("chapterPlanDetailCard").style.display = "none";
        currentChapterPlan = null;
      };

      // ========== Foreshadowing Kanban handlers ==========

      let currentForeshadowing = null;

      const foreshadowingStatuses = [
        { value: "planted", label: t("option.planted") },
        { value: "developing", label: t("option.developing") },
        { value: "ready_to_payoff", label: t("option.readyToPayoff") },
        { value: "paid_off", label: t("option.paidOff") },
        { value: "abandoned", label: t("option.abandoned") }
      ];

      const importanceColors = {
        low: "importance-low",
        medium: "importance-medium",
        high: "importance-high",
        critical: "importance-critical"
      };

      function renderForeshadowingKanban(items) {
        const board = $("foreshadowingKanban");
        const statusGroups = {};
        foreshadowingStatuses.forEach(s => statusGroups[s.value] = []);
        items.forEach(item => {
          if (statusGroups[item.status]) {
            statusGroups[item.status].push(item);
          } else {
            statusGroups["planted"].push(item);
          }
        });

        let html = '<div class="kanban-columns">';
        foreshadowingStatuses.forEach(status => {
          const itemsInStatus = statusGroups[status.value] || [];
          html += `
            <div class="kanban-column">
              <div class="kanban-column-header">
                <span>${status.label}</span>
                <span class="kanban-column-count">${itemsInStatus.length}</span>
              </div>
              <div class="kanban-column-content">
          `;
          itemsInStatus.forEach(item => {
            const isOverdue = item.is_overdue || false;
            const overdueClass = isOverdue ? "foreshadowing-card-overdue" : "";
            html += `
              <div class="foreshadowing-card ${importanceColors[item.importance] || "importance-medium"} ${overdueClass}" 
                   onclick="openForeshadowingDetail('${item.key}')">
                <div class="foreshadowing-card-header">
                  <span class="foreshadowing-card-key">[${item.key}]</span>
                  <span class="foreshadowing-card-importance">${item.importance}</span>
                </div>
                <div class="foreshadowing-card-title">${escapeHtml(item.title)}</div>
                ${item.expected_payoff_range ? `<div class="foreshadowing-card-range">${escapeHtml(item.expected_payoff_range)}</div>` : ""}
                ${isOverdue ? `<div class="foreshadowing-card-overdue-badge">⚠️ OVERDUE</div>` : ""}
              </div>
            `;
          });
          html += `
              </div>
            </div>
          `;
        });
        html += '</div>';
        board.innerHTML = html;
      }

      function renderForeshadowingDetail(item) {
        const content = $("foreshadowingDetailContent");
        content.innerHTML = `
          <div class="form-row">
            <div class="form-group">
              <label class="form-label" data-i18n="field.key">Key</label>
              <input class="form-input" id="fsDetailKey" value="${escapeHtml(item.key)}" readonly>
            </div>
            <div class="form-group">
              <label class="form-label" data-i18n="field.title">Title</label>
              <input class="form-input" id="fsDetailTitle" value="${escapeHtml(item.title)}">
            </div>
          </div>
          <div class="form-row">
            <div class="form-group">
              <label class="form-label" data-i18n="field.status">Status</label>
              <select class="form-select" id="fsDetailStatus">
                ${foreshadowingStatuses.map(s => `<option value="${s.value}" ${item.status === s.value ? "selected" : ""}>${s.label}</option>`).join("")}
              </select>
            </div>
            <div class="form-group">
              <label class="form-label" data-i18n="field.importance">Importance</label>
              <select class="form-select" id="fsDetailImportance">
                <option value="low" ${item.importance === "low" ? "selected" : ""}>low</option>
                <option value="medium" ${item.importance === "medium" ? "selected" : ""}>medium</option>
                <option value="high" ${item.importance === "high" ? "selected" : ""}>high</option>
                <option value="critical" ${item.importance === "critical" ? "selected" : ""}>critical</option>
              </select>
            </div>
          </div>
          <div class="form-row">
            <div class="form-group">
              <label class="form-label" data-i18n="field.layer">Layer</label>
              <select class="form-select" id="fsDetailLayer">
                <option value="visible" ${item.layer === "visible" ? "selected" : ""}>visible</option>
                <option value="hidden" ${item.layer === "hidden" ? "selected" : ""}>hidden</option>
                <option value="subtle" ${item.layer === "subtle" ? "selected" : ""}>subtle</option>
              </select>
            </div>
            <div class="form-group">
              <label class="form-label" data-i18n="field.expectedPayoff">Expected Payoff Range</label>
              <input class="form-input" id="fsDetailRange" value="${escapeHtml(item.expected_payoff_range || "")}">
            </div>
          </div>
          <div class="form-row">
            <div class="form-group">
              <label class="form-label" data-i18n="field.deadlineChapter">Payoff Deadline Chapter</label>
              <input class="form-input" type="number" id="fsDetailDeadlineChapter" value="${item.payoff_deadline_chapter || ""}">
            </div>
            <div class="form-group">
              <label class="form-label" data-i18n="field.deadlineVolume">Payoff Deadline Volume</label>
              <input class="form-input" type="number" id="fsDetailDeadlineVolume" value="${item.payoff_deadline_volume || ""}">
            </div>
          </div>
          <div class="form-group">
            <label class="form-label" data-i18n="field.mustPayoff">Must Payoff</label>
            <input type="checkbox" id="fsDetailMustPayoff" ${item.must_payoff ? "checked" : ""}>
          </div>
          <div class="form-group">
            <label class="form-label" data-i18n="field.payload">Payload (JSON)</label>
            <textarea class="form-textarea" id="fsDetailPayload" rows="4">${escapeHtml(JSON.stringify(item.payload || {}, null, 2))}</textarea>
          </div>
        `;
        $("foreshadowingDetailTitle").textContent = `Foreshadowing: ${item.title}`;
        $("foreshadowingDetailCard").style.display = "block";
      }

      function openForeshadowingDetail(key) {
        const base = getActiveProjectArgs();
        if (!base) return;
        setStatus(t("status.running"));
        api("/api/tool", { tool: "plot.list_foreshadowing", arguments: { ...base, statuses: [] } })
          .then(result => {
            if (result.ok && Array.isArray(result.result)) {
              const item = result.result.find(i => i.key === key);
              if (item) {
                currentForeshadowing = item;
                renderForeshadowingDetail(item);
                setStatus(t("msg.loaded"));
              } else {
                setStatus(t("status.error") + ": not found");
              }
            }
          });
      }

      // ========== Volume handlers ==========

      function renderVolumes(volumes) {
        const container = $("volumesResult");
        if (!volumes || volumes.length === 0) {
          container.innerHTML = '<p style="color:var(--muted);text-align:center;padding:20px;">No volumes</p>';
          return;
        }
        container.innerHTML = volumes.map(v => `
          <div class="list-item" onclick="selectVolume(${v.volume_no})">
            <div class="list-item-header">
              <span>Vol. ${v.volume_no}: ${v.title || 'Untitled'}</span>
              <span class="badge ${v.status === 'writing' ? 'badge-warning' : v.status === 'completed' ? 'badge-success' : 'badge-active'}">${v.status}</span>
            </div>
            <div class="list-item-meta">
              Ch. ${v.start_chapter_no || '-'} - ${v.end_chapter_no || '-'}
              ${v.outline ? ` | ${escapeHtml(v.outline.substring(0, 80))}...` : ''}
            </div>
          </div>
        `).join("");
      }

      window.selectVolume = async (volumeNo) => {
        const base = getActiveProjectArgs();
        if (!base) return;
        setStatus(t("status.running"));
        const result = await api("/api/tool", { tool: "volume.list", arguments: { ...base } });
        if (result.ok && Array.isArray(result.result)) {
          const volume = result.result.find(v => v.volume_no === volumeNo);
          if (volume) {
            $("volumeDetailTitle").textContent = `Volume ${volumeNo}`;
            $("volumeNo").value = volume.volume_no;
            $("volumeTitle").value = volume.title || "";
            $("volumeStatus").value = volume.status || "planned";
            $("volumeStartChapter").value = volume.start_chapter_no || "";
            $("volumeEndChapter").value = volume.end_chapter_no || "";
            $("volumeOutline").value = volume.outline || "";
            $("volumeSummary").value = volume.summary || "";
            $("volumeDetailCard").style.display = "block";
            setStatus(t("msg.loaded"));
          }
        }
      };

      $("volumeListBtn").onclick = async () => {
        const base = getActiveProjectArgs();
        if (!base) return;
        setStatus(t("status.running"));
        const statuses = $("volumeFilterStatus").value ? [$("volumeFilterStatus").value] : null;
        const result = await api("/api/tool", { tool: "volume.list", arguments: { ...base, statuses } });
        if (result.ok && Array.isArray(result.result)) {
          renderVolumes(result.result);
          setStatus(t("msg.loaded"));
        } else {
          setStatus(t("status.error"));
        }
      };

      $("volumeCreateBtn").onclick = () => {
        $("volumeDetailTitle").textContent = "New Volume";
        $("volumeNo").value = "";
        $("volumeTitle").value = "";
        $("volumeStatus").value = "planned";
        $("volumeStartChapter").value = "";
        $("volumeEndChapter").value = "";
        $("volumeOutline").value = "";
        $("volumeSummary").value = "";
        $("volumeDetailCard").style.display = "block";
      };

      $("volumeSaveBtn").onclick = async () => {
        const base = getActiveProjectArgs();
        if (!base) return;
        const volumeNo = parseInt($("volumeNo").value);
        if (!volumeNo) { setStatus(t("status.error") + ": volume number required"); return; }
        setStatus(t("status.running"));
        const result = await api("/api/tool", {
          tool: "volume.upsert",
          arguments: {
            ...base,
            volume_no: volumeNo,
            title: $("volumeTitle").value,
            status: $("volumeStatus").value,
            start_chapter_no: parseInt($("volumeStartChapter").value) || null,
            end_chapter_no: parseInt($("volumeEndChapter").value) || null,
            outline: $("volumeOutline").value || null,
            summary: $("volumeSummary").value || null
          }
        });
