      // ==========
      function renderPagination(containerId, currentPage, totalPages, loadFn) {
        var container = $(containerId);
        if (!container || totalPages <= 1) { if (container) container.innerHTML = ""; return; }
        var html = '<button class="pagination-btn" ' + (currentPage <= 1 ? 'disabled' : '') + ' onclick="' + loadFn + '(' + (currentPage - 1) + ')">‹</button>';
        var start = Math.max(1, currentPage - 2);
        var end = Math.min(totalPages, currentPage + 2);
        if (start > 1) { html += '<button class="pagination-btn" onclick="' + loadFn + '(1)">1</button>'; if (start > 2) html += '<span class="pagination-info">...</span>'; }
        for (var i = start; i <= end; i++) {
          html += '<button class="pagination-btn ' + (i === currentPage ? 'active' : '') + '" onclick="' + loadFn + '(' + i + ')">' + i + '</button>';
        }
        if (end < totalPages) { if (end < totalPages - 1) html += '<span class="pagination-info">...</span>'; html += '<button class="pagination-btn" onclick="' + loadFn + '(' + totalPages + ')">' + totalPages + '</button>'; }
        html += '<button class="pagination-btn" ' + (currentPage >= totalPages ? 'disabled' : '') + ' onclick="' + loadFn + '(' + (currentPage + 1) + ')">›</button>';
        html += '<span class="pagination-info">第 ' + currentPage + ' / ' + totalPages + ' 页</span>';
        container.innerHTML = html;
      }

