    // ========== Pipeline ==========
    async function runPipeline() {
      var projectId = $("pipelineProjectSelect").value;
      var chapterNo = parseInt($("pipelineChapterNo").value);
      var targetWords = parseInt($("pipelineTargetWords").value);
      var purpose = $("pipelinePurpose").value;
      if (!projectId) { showToast("warning", "请先选择项目"); return; }
      if (!chapterNo) { showToast("warning", "请输入章节号"); return; }

      $("pipelineStatus").style.display = "none";
      $("pipelineResult").style.display = "block";
      $("pipelinePassStatus").textContent = "正在生成章纲...";

      setStatus("生成章纲...");
      var ctxResult = await api("/api/tool", {
        tool: "workflow.prepare_chapter_context",
        arguments: Object.assign(baseProjectArgs(), { chapter_no: chapterNo, purpose: "outline" })
      });

      var outlineText = "# 第 " + chapterNo + " 章 章纲\n\n" + (ctxResult.warnings ? "注意: " + JSON.stringify(ctxResult.warnings) : "无");
      await api("/api/tool", {
        tool: "local.chapter.write_outline",
        arguments: { project_id: projectId, chapter_no: chapterNo, outline: outlineText }
      });
      $("pipelinePass1").className = "badge badge-success";
      $("pipelinePassStatus").textContent = "章纲已生成，正在生成初稿...";

      setStatus("生成初稿...");
      var draftResult = await api("/api/tool", {
        tool: "workflow.prepare_chapter_context",
        arguments: Object.assign(baseProjectArgs(), { chapter_no: chapterNo, purpose: purpose })
      });
      var draftText = "# 第 " + chapterNo + " 章\n\n" + (draftResult.warnings ? "注意: " + JSON.stringify(draftResult.warnings) : "内容待生成");
      await api("/api/tool", {
        tool: "local.chapter.write",
        arguments: { project_id: projectId, chapter_no: chapterNo, content: draftText, version: purpose }
      });
      $("pipelinePass2").className = "badge badge-success";
      $("pipelinePassStatus").textContent = "初稿已生成，正在审查...";

      setStatus("多模型审查...");
      var reviewText = "# 审查报告\n\n模型: default\n评分: 待评估\n问题: 无";
      await api("/api/tool", {
        tool: "local.review.write",
        arguments: { project_id: projectId, chapter_no: chapterNo, model_name: "default", report: reviewText, score: 75, passed: true }
      });
      $("pipelinePass3").className = "badge badge-success";
      $("pipelinePassStatus").textContent = "生成完成！";

      showToast("success", "第 " + chapterNo + " 章生成完成", "已保存到本地目录");

      if (currentPage === "local-chapters") loadLocalChapters();
    }

    // ========== Knowledge Pack ==========
    var currentPackProjectId = null;
    var currentPackActive = [];
    var currentPackCustom = {};
    var allCategories = ["角色", "物品装备", "生物生态", "世界设定", "力量体系", "历史文化", "情节参考", "写作参考", "通用素材"];

    async function loadKnowledgePack() {
      var projectId = $("packProjectSelect").value;
      if (!projectId) { $("packActiveCategories").innerHTML = '<p style="color:var(--muted);">请先选择项目</p>'; return; }
      currentPackProjectId = projectId;

      // Load project pack
      var result = await api("/api/tool", { tool: "kb.pack.get", arguments: { project_id: projectId } });
      if (result && result.error) {
        $("packActiveCategories").innerHTML = '<p style="color:var(--muted);">该项目暂无知识包，请先创建</p>';
        $("packInactiveCategories").innerHTML = '';
        $("packCustomCategories").innerHTML = '';
        return;
      }
      if (result) {
        currentPackActive = result.active_categories || [];
        currentPackCustom = result.custom_categories || {};
        $("packGenreSelect").value = result.genre || "";
      }

      // Render active categories
      var activeHtml = currentPackActive.map(function(cat) {
        return '<span class="badge badge-success" style="cursor:pointer;padding:8px 12px;" onclick="toggleCategory(\'' + cat + '\')">' + escapeHtml(cat) + ' ✕</span>';
      }).join("");
      $("packActiveCategories").innerHTML = activeHtml || '<p style="color:var(--muted);">无启用分类</p>';

      // Render inactive categories
      var inactive = allCategories.filter(function(c) { return currentPackActive.indexOf(c) === -1; });
      var inactiveHtml = inactive.map(function(cat) {
        return '<span class="badge" style="cursor:pointer;padding:8px 12px;" onclick="toggleCategory(\'' + cat + '\')">' + escapeHtml(cat) + ' +</span>';
      }).join("");
      $("packInactiveCategories").innerHTML = inactiveHtml || '<p style="color:var(--muted);">所有分类已启用</p>';

      // Render custom categories
      var customKeys = Object.keys(currentPackCustom);
      var customHtml = customKeys.map(function(name) {
        var cat = currentPackCustom[name];
        return '<div class="list-item">' +
          '<div class="list-item-header"><span style="font-weight:500;">' + escapeHtml(name) + '</span>' +
          '<button class="btn btn-sm" style="background:var(--danger);color:#fff;" onclick="removeCustomCategory(\'' + name + '\')">删除</button></div>' +
          '<div class="list-item-meta">' + (cat.parent ? "父分类: " + escapeHtml(cat.parent) : "无父分类") + (cat.description ? " — " + escapeHtml(cat.description) : "") + '</div>' +
          '</div>';
      }).join("");
      $("packCustomCategories").innerHTML = customHtml || '<p style="color:var(--muted);">暂无自定义分类</p>';
    }

    async function createKnowledgePack() {
      var projectId = $("packProjectSelect").value;
      var genre = $("packGenreSelect").value;
      if (!projectId || !genre) { showToast("warning", "请选择项目和小说类型"); return; }
      setStatus("创建知识包...");
      var result = await api("/api/tool", { tool: "kb.pack.create", arguments: { project_id: projectId, genre: genre } });
      if (result && !result.error) {
        showToast("success", "知识包已创建", genre + " 类型配置已应用");
        loadKnowledgePack();
      }
    }

    function toggleCategory(cat) {
      var idx = currentPackActive.indexOf(cat);
      if (idx >= 0) {
        currentPackActive.splice(idx, 1);
      } else {
        currentPackActive.push(cat);
      }
      // Re-render
      var activeHtml = currentPackActive.map(function(c) {
        return '<span class="badge badge-success" style="cursor:pointer;padding:8px 12px;" onclick="toggleCategory(\'' + c + '\')">' + escapeHtml(c) + ' ✕</span>';
      }).join("");
      $("packActiveCategories").innerHTML = activeHtml;

      var inactive = allCategories.filter(function(c) { return currentPackActive.indexOf(c) === -1; });
      var inactiveHtml = inactive.map(function(c) {
        return '<span class="badge" style="cursor:pointer;padding:8px 12px;" onclick="toggleCategory(\'' + c + '\')">' + escapeHtml(c) + ' +</span>';
      }).join("");
      $("packInactiveCategories").innerHTML = inactiveHtml;
    }

    async function addCustomCategory() {
      var name = $("customCatName").value.trim();
      var parent = $("customCatParent").value.trim();
      if (!name) { showToast("warning", "请输入分类名称"); return; }
      if (!currentPackProjectId) { showToast("warning", "请先选择项目"); return; }
      setStatus("添加自定义分类...");
      var result = await api("/api/tool", { tool: "kb.pack.custom.add", arguments: { project_id: currentPackProjectId, name: name, parent: parent || null } });
      if (result && !result.error) {
        showToast("success", "自定义分类已添加");
        $("customCatName").value = "";
        $("customCatParent").value = "";
        loadKnowledgePack();
      }
    }

    async function removeCustomCategory(name) {
      if (!confirm("确定要删除自定义分类 \"" + name + "\" 吗？")) return;
      var result = await api("/api/tool", { tool: "kb.pack.custom.remove", arguments: { project_id: currentPackProjectId, name: name } });
      if (result && !result.error) {
        showToast("success", "自定义分类已删除");
        loadKnowledgePack();
      }
    }

